/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_estudio_ai` AFTER INSERT ON `estudio` FOR EACH ROW INSERT INTO bitacora (tabla, registro_id, accion, usuario_db, detalle)
  VALUES ('estudio', NEW.id, 'INSERT', CURRENT_USER(), JSON_OBJECT('estado', NEW.estado, 'paciente_id', NEW.paciente_id)) */;;
